      let code = fDesc.getCode();
      const selectImpl = selectBuffer ? ["  var compositeID: u32 = input.compositeID;", "  var attributeID: u32 = input.attributeID;"] : ["  var compositeID: u32 = 0u;", "  var attributeID: u32 = 0u;"];
